export { includesValue, itemView, rootView, toggleValue } from "../accordion";
export type {
  AccordionStyle,
  ItemViewConfig,
  RootViewConfig,
} from "../accordion";

export {
  shadcnAccordionHeaderClassName,
  shadcnAccordionIconClassName,
  shadcnAccordionItemClassName,
  shadcnAccordionPanelClassName,
  shadcnAccordionRootClassName,
  shadcnAccordionTriggerClassName,
} from "./view";

export const shadcnAccordionRootClassName = "w-full max-w-2xl bg-white";

export const shadcnAccordionItemClassName =
  "border-b border-gray-200 data-[disabled]:opacity-50 data-[open]:bg-gray-50";

export const shadcnAccordionHeaderClassName = "m-0";

export const shadcnAccordionTriggerClassName =
  "group flex w-full cursor-pointer items-center justify-between gap-4 px-4 py-3 text-left text-sm font-medium text-gray-950 transition hover:bg-gray-50 focus-visible:outline-2 focus-visible:outline-inset focus-visible:outline-accent-600 data-[disabled]:cursor-not-allowed";

export const shadcnAccordionIconClassName =
  "text-gray-500 transition-transform group-data-[open]:rotate-45";

export const shadcnAccordionPanelClassName =
  "px-4 pb-4 text-sm leading-6 text-gray-600";

import { describe, expect, test } from "vitest";

import * as Accordion from "./index";

describe("shadcn Accordion registry view", () => {
  test("reuses the Foldkit Accordion view contract", () => {
    expect(Accordion.rootView).toBeTypeOf("function");
    expect(Accordion.itemView).toBeTypeOf("function");
    expect(Accordion.toggleValue(["one"], "one")).toEqual([]);
    expect(Accordion.shadcnAccordionRootClassName).not.toContain("border");
    expect(Accordion.shadcnAccordionItemClassName).toContain("border-b");
    expect(Accordion.shadcnAccordionTriggerClassName).toContain("font-medium");
  });
});
